// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address depositor, uint256 amount) public {
        vm.assume(depositor != address(0) && depositor != address(c));
        uint256 depositAmount = bound(amount, 1, 100 ether);
        vm.deal(depositor, depositAmount);
        vm.prank(depositor);
        c.deposit{value: depositAmount}();
        uint256 balanceBefore = address(c).balance;
        address recipient = makeAddr("recipient");
        uint256 recipientBalanceBefore = recipient.balance;
        c.migrateTo(recipient);
        assertTrue(balanceBefore == recipient.balance - recipientBalanceBefore);
    }
}

